const root = document.querySelector('#questions');

function makeChoices(activity, index) {
  const list = document.createElement('div');
  list.className = 'answer-list';
  activity.options.forEach((option, optionIndex) => {
    const label = document.createElement('label');
    label.className = 'choice';
    const input = document.createElement('input');
    input.type = activity.type === 'multiple' ? 'checkbox' : 'radio';
    input.name = `activity-${index}`;
    input.value = optionIndex;
    const text = document.createElement('span');
    text.textContent = option;
    label.append(input, text);
    list.append(label);
  });
  return list;
}

function makeTrueFalse(activity, index) {
  const table = document.createElement('div');
  table.className = 'tf-table';
  const heading = document.createElement('div');
  heading.className = 'tf-heading';
  heading.innerHTML = '<span>Afirmação</span><span>V</span><span>F</span>';
  table.append(heading);
  activity.statements.forEach((statement, rowIndex) => {
    const row = document.createElement('div');
    row.className = 'tf-row';
    const text = document.createElement('p');
    text.innerHTML = `<strong>${String.fromCharCode(97 + rowIndex)}.</strong> ${statement}`;
    row.append(text);
    ['V', 'F'].forEach(value => {
      const label = document.createElement('label');
      label.className = 'tf-choice';
      label.setAttribute('aria-label', `${value}: ${statement}`);
      const input = document.createElement('input');
      input.type = 'radio';
      input.name = `activity-${index}-statement-${rowIndex}`;
      input.value = value;
      label.append(input);
      row.append(label);
    });
    table.append(row);
  });
  return table;
}

activities.forEach((activity, index) => {
  const card = document.createElement('article');
  card.className = 'question';
  card.id = `activity-${index}`;
  const head = document.createElement('div');
  head.className = 'q-head';
  head.innerHTML = `<span class="q-number">${index + 1}</span><h2 class="q-title">${activity.title}</h2>`;
  const body = document.createElement('div');
  body.className = 'q-body';
  const prompt = document.createElement('p');
  prompt.className = 'q-context';
  prompt.textContent = activity.prompt;
  body.append(prompt);
  if (activity.figure) {
    const figure = document.createElement('figure');
    figure.className = 'question-figure';
    const image = document.createElement('img');
    image.src = activity.figure;
    image.alt = activity.alt;
    image.loading = 'eager';
    figure.append(image);
    body.append(figure);
  }
  body.append(activity.type === 'truefalse' ? makeTrueFalse(activity, index) : makeChoices(activity, index));
  const actions = document.createElement('div');
  actions.className = 'q-actions';
  actions.innerHTML = '<button class="button small-check" type="button">Corrigir atividade</button><span class="q-status" aria-live="polite"></span>';
  actions.querySelector('button').addEventListener('click', () => checkActivity(index));
  body.append(actions);
  card.append(head, body);
  root.append(card);
});

function selectedIndexes(index) {
  return [...document.querySelectorAll(`#activity-${index} input:checked`)]
    .filter(input => input.name === `activity-${index}`)
    .map(input => Number(input.value));
}

function checkActivity(index) {
  const activity = activities[index];
  const card = document.querySelector(`#activity-${index}`);
  let complete = false;
  if (activity.type === 'truefalse') {
    const answers = activity.statements.map((_, row) => card.querySelector(`input[name="activity-${index}-statement-${row}"]:checked`)?.value);
    complete = answers.every((answer, i) => answer === activity.correct[i]);
    card.querySelector('.q-status').textContent = answers.every(Boolean)
      ? (complete ? 'Atividade concluída.' : 'Reveja as respostas e tente novamente.')
      : 'Responde às quatro afirmações.';
  } else {
    const chosen = selectedIndexes(index).sort((a, b) => a - b);
    const expected = [...activity.correct].sort((a, b) => a - b);
    complete = chosen.length === expected.length && chosen.every((value, i) => value === expected[i]);
    card.querySelector('.q-status').textContent = chosen.length
      ? (complete ? 'Atividade concluída.' : 'Reveja a resposta e tente novamente.')
      : 'Ainda não respondeste.';
  }
  card.classList.toggle('done', complete);
  updateProgress();
}

function updateProgress() {
  const done = activities.filter((_, index) => document.querySelector(`#activity-${index}`).classList.contains('done')).length;
  const percent = Math.round(done / activities.length * 100);
  document.querySelector('#progress-label').textContent = `${done} de ${activities.length} atividades concluídas`;
  document.querySelector('#progress-percent').textContent = `${percent}%`;
  document.querySelector('#progress-bar').style.width = `${percent}%`;
}

document.querySelector('#check-all').addEventListener('click', () => activities.forEach((_, index) => checkActivity(index)));
document.querySelector('#reset').addEventListener('click', () => {
  document.querySelectorAll('#questions input').forEach(input => { input.checked = false; });
  document.querySelectorAll('.q-status').forEach(status => { status.textContent = ''; });
  document.querySelectorAll('.question').forEach(card => card.classList.remove('done'));
  updateProgress();
});

